actions.script:
import org.moqui.entity.EntityCondition
modes = []
if (!ec.user.isInGroup('ADMIN') && ec.user.context.activeOrgId != organizationPartyId) return
def cf = ec.entity.conditionFactory
def equals = EntityCondition.ComparisonOperator.EQUALS
def candidates = ec.entity.find('zenith.erp.pos.PosSalesMode').condition('isActive','Y')
    .condition(cf.makeCondition([
        cf.makeCondition('organizationPartyId',equals,organizationPartyId),
        cf.makeCondition('organizationPartyId',equals,null)
    ], EntityCondition.JoinOperator.OR)).orderBy('-isDefault,modeName,salesModeId').disableAuthz().list()
def defaults = ['RETAIL','WHOLESALE']
def removed = ec.entity.find('zenith.erp.pos.PosSalesModeOrgRemoval').condition('organizationPartyId',organizationPartyId)
    .selectField('salesModeId').disableAuthz().list()*.salesModeId as Set
def legacy = candidates.findAll { !it.organizationPartyId && !defaults.contains(it.salesModeId) && !removed.contains(it.salesModeId) }*.salesModeId
def configured = [] as Set
if (legacy) {
    // Old terminal mappings may have been auto-populated. Keep only deliberately configured shared extras.
    for (def entityName in ['zenith.erp.pos.PosSalesModeOrgConfig','zenith.erp.pos.PosProductModePrice']) {
        configured.addAll(ec.entity.find(entityName).condition('organizationPartyId',organizationPartyId)
            .condition('salesModeId','in',legacy).selectField('salesModeId').distinct(true).disableAuthz().list()*.salesModeId)
    }
}
def ownedDefault = candidates.any { it.organizationPartyId == organizationPartyId && it.isDefault == 'Y' }
modes = candidates.findAll {
    (it.organizationPartyId || defaults.contains(it.salesModeId) || configured.contains(it.salesModeId)) &&
    (!removed.contains(it.salesModeId) || (it.salesModeId == 'RETAIL' && !ownedDefault))
}

def terminal = ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).one()
def removed = ec.entity.find('zenith.erp.pos.PosSalesModeShop')
    .condition('organizationPartyId',access.organizationPartyId).condition('facilityId',terminal.facilityId).list()*.salesModeId as Set
def assigned = ec.entity.find('zenith.erp.pos.PosTerminalSalesMode')
    .condition('terminalId',terminalId).condition('isActive','Y').list()*.salesModeId as Set
assigned.retainAll(organizationModes.modes*.salesModeId)
modes = organizationModes.modes.findAll {
    it.isDefault == 'Y' || ((!assigned || assigned.contains(it.salesModeId)) && !removed.contains(it.salesModeId))
}

def org = access.organizationPartyId
// Mode changes/adds lock their terminal; lock the same rows before checking open carts.
ec.entity.find('zenith.erp.pos.PosTerminal').condition('organizationPartyId',org).orderBy('terminalId').forUpdate(true).list()
def mode = ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',salesModeId).forUpdate(true).one()
if (!mode || (mode.organizationPartyId && mode.organizationPartyId != org) || mode.isDefault == 'Y') {
    ec.message.addError('This sales mode cannot be deleted. The default Retail mode must remain available.'); return
}
if (ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',org).condition('salesModeId',salesModeId).condition('statusId','in',['PtCreated','PtHeld']).count() > 0) {
    ec.message.addError('Finish, switch or void open and held carts using this mode before deleting it.'); return
}
def itemUse = ec.entity.find('zenith.erp.pos.PosTransactionItem')
itemUse.makeEntityDynamicView()
    .addMemberEntity('I','zenith.erp.pos.PosTransactionItem',null,null,null)
    .addMemberEntity('T','zenith.erp.pos.PosTransaction','I',false,[transactionId:'transactionId'])
    .addAlias('I','salesModeId').addAlias('T','organizationPartyId').addAlias('T','statusId')
if (itemUse.condition('organizationPartyId',org).condition('salesModeId',salesModeId).condition('statusId','in',['PtCreated','PtHeld']).count() > 0) {
    ec.message.addError('Finish, switch or void open and held carts using this mode before deleting it.'); return
}
// Preserve prices and issued bills; never deactivate a definition shared with another tenant.
if (mode.organizationPartyId == org) mode.set('isActive','N').update()
else ec.service.sync().name('store#zenith.erp.pos.PosSalesModeOrgRemoval').parameters([organizationPartyId:org,salesModeId:salesModeId]).call()
ec.message.addMessage('Sales mode deleted from your organization. Existing bills and other organizations are unchanged.')

def ids = (facilityIds ?: []).findAll { it }.collect { it.toString() }.unique().sort()
def mode = ec.entity.find('zenith.erp.pos.PosSalesMode').condition('salesModeId',salesModeId).one()
if (!mode || mode.isActive != 'Y' || (mode.organizationPartyId && mode.organizationPartyId != access.organizationPartyId)) {
    ec.message.addError('Choose an active sales mode from your organization.'); return
}
if (mode.isDefault == 'Y') { ec.message.addError('The default Retail mode must remain available.'); return }
if (ec.entity.find('zenith.erp.pos.PosSalesModeOrgRemoval').condition('organizationPartyId',access.organizationPartyId).condition('salesModeId',salesModeId).count()) { ec.message.addError('This sales mode has been deleted from your organization.'); return }
if (!ids || ids.size() > 100) { ec.message.addError('Select the shop or shops to update.'); return }
def shops = ec.entity.find('mantle.facility.Facility').condition('facilityId','in',ids)
    .condition('ownerPartyId',access.organizationPartyId).condition('facilityTypeEnumId','FcTpRetailStore').list()
if (shops.size() != ids.size()) { ec.message.addError('Choose only shops belonging to your active organization.'); return }
def terminals = ec.entity.find('zenith.erp.pos.PosTerminal').condition('organizationPartyId',access.organizationPartyId)
    .condition('facilityId','in',ids).orderBy('terminalId').forUpdate(true).list()
if (!restore && terminals) {
    def sessions = ec.entity.find('zenith.erp.pos.PosSession').condition('organizationPartyId',access.organizationPartyId)
        .condition('terminalId','in',terminals*.terminalId).list()*.sessionId
    if (sessions) {
        def carts = ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',access.organizationPartyId)
            .condition('sessionId','in',sessions).condition('statusId','in',['PtCreated','PtHeld']).list()
        def used = carts.any { it.salesModeId == salesModeId }
        if (!used && carts) used = ec.entity.find('zenith.erp.pos.PosTransactionItem')
            .condition('transactionId','in',carts*.transactionId).condition('salesModeId',salesModeId).count() > 0
        if (used) { ec.message.addError('Finish, switch or void open and held carts using this mode in the selected shops first.'); return }
    }
}
// Validate the complete selection before writing any shop override.
ids.each { id ->
    if (restore) ec.entity.find('zenith.erp.pos.PosSalesModeShop').condition('organizationPartyId',access.organizationPartyId)
        .condition('facilityId',id).condition('salesModeId',salesModeId).deleteAll()
    else ec.service.sync().name('store#zenith.erp.pos.PosSalesModeShop').parameters([
        facilityId:id,salesModeId:salesModeId,organizationPartyId:access.organizationPartyId]).call()
}
ec.message.addMessage(restore ? 'Sales mode restored for the selected shop.' : 'Sales mode removed from the selected shops. Other shops and bill history are unchanged.')
